namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Level { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public string CourseId { get; set; } = "";
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = "eng", Name = "English", Description = "Literature, composition, creative writing, and linguistics." },
        new() { Id = "phys", Name = "Physics", Description = "Fundamental principles of matter, energy, and the universe." },
        new() { Id = "hist", Name = "History", Description = "World history, civilizations, and historical research methods." },
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = "CS101", Title = "Introduction to Programming", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Level = "Introductory", IsFeatured = true,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Bio = "Specializes in programming language design and CS education with 12 years of teaching experience.", Email = "alovelace@university.edu" }
            },
            new()
            {
                Id = "CS201", Title = "Data Structures & Algorithms", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm analysis. Emphasizes problem-solving and computational thinking.",
                Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM", Level = "Intermediate",
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Bio = "Renowned researcher in theoretical computer science and algorithm design.", Email = "aturing@university.edu" }
            },
            new()
            {
                Id = "CS310", Title = "Database Systems", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Relational database design, SQL, normalization, indexing, and transaction management. Includes a semester-long project building a real-world database application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Level = "Intermediate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Edgar Codd", Title = "Associate Professor", Bio = "Expert in relational database theory and distributed data systems.", Email = "ecodd@university.edu" }
            },
            new()
            {
                Id = "CS420", Title = "Machine Learning", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Introduction to machine learning techniques including supervised learning, neural networks, and model evaluation. Prerequisites: CS201, MATH202.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Level = "Advanced",
                Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Bio = "Pioneer in machine learning applications with over 50 published papers.", Email = "ghopper@university.edu" }
            },
            new()
            {
                Id = "MATH101", Title = "Calculus I", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Level = "Introductory", IsFeatured = true,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Award-winning educator specializing in abstract algebra and calculus pedagogy.", Email = "enoether@university.edu" }
            },
            new()
            {
                Id = "MATH202", Title = "Linear Algebra", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Level = "Intermediate",
                Instructor = new() { Name = "Dr. Carl Gauss", Title = "Associate Professor", Bio = "Focuses on numerical linear algebra and computational mathematics.", Email = "cgauss@university.edu" }
            },
            new()
            {
                Id = "MATH305", Title = "Probability & Statistics", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.",
                Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", Level = "Intermediate",
                Instructor = new() { Name = "Dr. Florence Nightingale", Title = "Assistant Professor", Bio = "Statistician with research interests in biostatistics and data visualization.", Email = "fnightingale@university.edu" }
            },
            new()
            {
                Id = "ENG101", Title = "Expository Writing", DepartmentId = "eng", DepartmentName = "English",
                Description = "Develop clear, effective prose through essays and research papers. Emphasis on argumentation, evidence, and revision.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Level = "Introductory",
                Instructor = new() { Name = "Dr. Maya Angelou", Title = "Professor", Bio = "Acclaimed author and writing instructor with a focus on voice and narrative craft.", Email = "mangelou@university.edu" }
            },
            new()
            {
                Id = "ENG220", Title = "American Literature", DepartmentId = "eng", DepartmentName = "English",
                Description = "Survey of major American literary works from the colonial period to the present. Explores themes of identity, democracy, and culture.",
                Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Level = "Intermediate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Toni Morrison", Title = "Professor", Bio = "Literary scholar specializing in 20th-century American fiction and cultural criticism.", Email = "tmorrison@university.edu" }
            },
            new()
            {
                Id = "PHYS101", Title = "General Physics I", DepartmentId = "phys", DepartmentName = "Physics",
                Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", Level = "Introductory",
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Professor", Bio = "Celebrated physics educator known for making complex topics accessible and engaging.", Email = "rfeynman@university.edu" }
            },
            new()
            {
                Id = "PHYS210", Title = "Electromagnetism", DepartmentId = "phys", DepartmentName = "Physics",
                Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
                Credits = 4, Schedule = "Tue/Thu 10:00–11:15 AM + Fri Lab 1:00–3:00 PM", Level = "Intermediate",
                Instructor = new() { Name = "Dr. Marie Curie", Title = "Associate Professor", Bio = "Researcher in experimental physics with expertise in electromagnetic theory.", Email = "mcurie@university.edu" }
            },
            new()
            {
                Id = "HIST101", Title = "World Civilizations", DepartmentId = "hist", DepartmentName = "History",
                Description = "Survey of major world civilizations from antiquity to the modern era. Examines political, social, and cultural developments.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Level = "Introductory",
                Instructor = new() { Name = "Dr. Howard Zinn", Title = "Professor", Bio = "Historian focused on social movements, labor history, and people's history perspectives.", Email = "hzinn@university.edu" }
            },
            new()
            {
                Id = "HIST250", Title = "Modern European History", DepartmentId = "hist", DepartmentName = "History",
                Description = "Europe from the Enlightenment to the present. Covers revolutions, industrialization, world wars, and the European Union.",
                Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", Level = "Intermediate", IsFeatured = true,
                Instructor = new() { Name = "Dr. Eric Hobsbawm", Title = "Professor", Bio = "Specialist in modern European social and economic history.", Email = "ehobsbawm@university.edu" }
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? departmentId = null, string? level = null, string? search = null)
    {
        IEnumerable<Course> query = _courses;

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(level))
            query = query.Where(c => c.Level.Equals(level, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public List<string> GetLevels() => ["Introductory", "Intermediate", "Advanced"];

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && !string.IsNullOrWhiteSpace(request.CourseId)
            && GetCourse(request.CourseId) is not null;
    }
}

